import { queryExecutionClient } from '@dynatrace-sdk/client-query';
import { businessEventsClient } from '@dynatrace-sdk/client-classic-environment-v2';

// GENERATED by scripts/generate-snapshot-workflow.mjs - do not edit the QUERIES below by hand.
// The five queries are the leaderboard's BULK_L1..BULK_L5 from ui/app/queries/maturityQueries.ts, so the
// daily snapshot scores applications exactly as the live leaderboard does (including how an AppCI is
// resolved from tags and /lookups/appci_map). Edit that module, then run `npm run generate:workflows`.
// The template for everything else in this script is workflows/sre-maturity-daily-snapshot.script.template.js.
__QUERIES__

// Grail's query execution API silently caps a single query at 1000 result
// records unless maxResultRecords is raised explicitly (confirmed live:
// computeL5 returned exactly 1000 of ~1417 real distinct apps before this
// fix). The native dynatrace.automations:execute-dql-query workflow action
// does NOT forward a maxResultRecords-style input through to the
// underlying query — verified by testing it directly against this tenant
// (the "Your result has been limited to 1000" API warning still fired even
// with that field set on the task input). Calling queryExecutionClient
// directly, as this script does, is the one place maxResultRecords is
// actually honored.
const MAX_RESULT_RECORDS = 5000;

async function runQuery(query) {
  const start = await queryExecutionClient.queryExecute({
    body: { query, maxResultRecords: MAX_RESULT_RECORDS, requestTimeoutMilliseconds: 60000 },
  });
  let state = start.state;
  let result = start.result;
  let token = start.requestToken;
  while (state !== 'SUCCEEDED' && token) {
    // eslint-disable-next-line no-await-in-loop
    const poll = await queryExecutionClient.queryPoll({ requestToken: token });
    state = poll.state;
    result = poll.result;
    if (state === 'SUCCEEDED' || state === 'FAILED' || state === 'CANCELLED' || state === 'RESULT_GONE') break;
    // eslint-disable-next-line no-await-in-loop
    await new Promise((r) => setTimeout(r, 1000));
  }
  if (state !== 'SUCCEEDED') {
    throw new Error(`Query did not succeed (state=${state}): ${query.slice(0, 80)}...`);
  }
  const records = (result && result.records) || [];
  if (records.length >= MAX_RESULT_RECORDS) {
    // Still hit the ceiling even after raising it — surface this loudly
    // rather than silently under-counting; bump MAX_RESULT_RECORDS further
    // if this ever fires for real.
    // eslint-disable-next-line no-console
    console.warn(`Query returned ${records.length} records, at or above MAX_RESULT_RECORDS=${MAX_RESULT_RECORDS} — results may be truncated: ${query.slice(0, 80)}...`);
  }
  return records;
}

// Denominators must match ScorecardsPage.tsx's `L{n} Score` = concat(passCount, " / N")
// and checkDetailConfigs.ts's LEVEL_CHECK_COUNT (L1:7, L2:6, L3:7, L4:5, L5:5).
const LEVEL_MAX = { l1: 7, l2: 6, l3: 7, l4: 5, l5: 5 };
const LEVELS = ['l1', 'l2', 'l3', 'l4', 'l5'];
const TOTAL_MAX = LEVELS.reduce((s, k) => s + LEVEL_MAX[k], 0); // 30

// Mirrors ui/app/components/MaturitySpine.tsx's getCurrentLevel(): a
// cumulative 80%-gate walk up the levels, NOT MaturityLeaderboard.tsx's
// different single-threshold getMaturityLevel(pct) bucketing. The daily
// snapshot's grade must match the live scorecard's own grading.
function currentGrade(scores) {
  const THRESHOLD = 0.8;
  let idx = 0;
  for (let i = 0; i < LEVELS.length; i++) {
    const key = LEVELS[i];
    const pct = LEVEL_MAX[key] > 0 ? scores[key] / LEVEL_MAX[key] : 0;
    if (pct >= THRESHOLD) idx = Math.min(i + 1, LEVELS.length - 1);
    else { idx = i; break; }
  }
  return LEVELS[idx].toUpperCase(); // "L1".."L5"
}

function toMap(records, scoreField) {
  const m = new Map();
  for (const r of records || []) {
    const appci = String(r.applicationci || '').trim().toLowerCase();
    if (!appci) continue;
    m.set(appci, Number(r[scoreField] || 0));
  }
  return m;
}

export default async function () {
  const [l1, l2, l3, l4, l5] = await Promise.all([
    runQuery(QUERIES.l1), runQuery(QUERIES.l2), runQuery(QUERIES.l3),
    runQuery(QUERIES.l4), runQuery(QUERIES.l5),
  ]);

  const l1Map = toMap(l1, 'l1Score');
  const l2Map = toMap(l2, 'l2Score');
  const l3Map = toMap(l3, 'l3Score');
  const l4Map = toMap(l4, 'l4Score');
  const l5Map = toMap(l5, 'l5Score');

  // Union of every appci seen in ANY of the 5 result sets — deliberately not
  // anchored on l1Map only. MaturityLeaderboard.tsx's client-side merge
  // anchors on l1Map.entries() as "all apps," which would silently drop an
  // app that only appears in another level's independently-derived set.
  // Since the goal here is "snapshot every app," union is correct.
  const allAppci = new Set([
    ...l1Map.keys(), ...l2Map.keys(), ...l3Map.keys(), ...l4Map.keys(), ...l5Map.keys(),
  ]);

  const snapshotDate = new Date().toISOString().slice(0, 10); // YYYY-MM-DD

  const events = [];
  for (const appci of allAppci) {
    const scores = {
      l1: l1Map.get(appci) || 0, l2: l2Map.get(appci) || 0,
      l3: l3Map.get(appci) || 0, l4: l4Map.get(appci) || 0,
      l5: l5Map.get(appci) || 0,
    };
    const total = LEVELS.reduce((s, k) => s + scores[k], 0);
    const pct = Math.round((total / TOTAL_MAX) * 100);
    const grade = currentGrade(scores);

    events.push({
      specversion: '1.0',
      id: `${appci}-${snapshotDate}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      source: 'sre-maturity-daily-snapshot-workflow',
      type: 'workflow.summary.sre_maturity',
      time: new Date().toISOString(),
      data: {
        applicationci: appci,
        snapshotDate,
        l1Score: scores.l1, l2Score: scores.l2, l3Score: scores.l3,
        l4Score: scores.l4, l5Score: scores.l5,
        total, totalMax: TOTAL_MAX, pct, grade,
      },
    });
  }

  // Batches of 500 bound blast radius / retry granularity per network call —
  // not driven by the 5 MiB payload cap (at ~2,000 apps x ~400 bytes each, a
  // single batch is well under 1 MiB).
  const BATCH_SIZE = 500;
  let batchesOk = 0;
  const failedBatches = [];
  for (let i = 0; i < events.length; i += BATCH_SIZE) {
    const chunk = events.slice(i, i + BATCH_SIZE);
    try {
      await businessEventsClient.ingest({
        type: 'application/cloudevent-batch+json',
        body: chunk,
      });
      batchesOk++;
    } catch (err) {
      // A partially-invalid batch still ingests its valid events per
      // businessEventsClient.ingest's documented behavior — log and
      // continue so one bad record doesn't block the other apps.
      failedBatches.push({ startIndex: i, size: chunk.length, error: String(err) });
    }
  }

  return {
    appsProcessed: allAppci.size,
    recordCounts: { l1: l1.length, l2: l2.length, l3: l3.length, l4: l4.length, l5: l5.length },
    batchesTotal: Math.ceil(events.length / BATCH_SIZE),
    batchesOk,
    batchesFailed: failedBatches.length,
    failedBatches,
  };
}
